INSERT INTO `journal_encounter` (`Name`, `Description`, `MapX`, `MapY`, `ID`, `JournalInstanceID`, `DungeonEncounterID`, `OrderIndex`, `FirstSectionID`, `UiMapID`, `MapDisplayConditionID`, `Flags`, `DifficultyMask`, `VerifiedBuild`) VALUES
('Seranel Sunlash', 'An accomplished Spellbreaker, Serenel Sunlash has earned the full trust of the Magisters. Charged with the protection of the Cynosure of Twilight, Seranel will fulfill those duties with his very life if necessary.', 0.558996975421905517, 0.333629012107849121, 2661, 1300, 3072, 2, 30544, 2516, 0, 0, -1, 65893),
('Affixes', 'Affixes are modifiers attached to the Keystone that alter gameplay in Mythic Keystone dungeons. They are introduced at Mythic Level 2, with adjustments at Mythic Levels 5, 7, 10, and 12.', 0.5, 0.5, 2870, 1319, 3426, 0, 34716, 0, 0, 0, -1, 65893),
('Midnight Falls', 'Once a creature of Light, L\'ura fell to the Void long ago on Argus, her essence siphoned by Alleria Windrunner in the Seat of the Triumvirate. Freed from her bindings, L\'ura\'s dark energies now threaten the very Sunwell itself.', 0.510313987731933593, 0.440928012132644653, 2740, 1308, 3183, 1, 32163, 2534, 0, 0, -1, 65893);
INSERT INTO `journal_encounter_section` (`ID`, `Title`, `BodyText`, `JournalEncounterID`, `OrderIndex`, `ParentSectionID`, `FirstChildSectionID`, `NextSiblingSectionID`, `Type`, `IconCreatureDisplayInfoID`, `UiModelSceneID`, `SpellID`, `IconFileDataID`, `Flags`, `IconFlags`, `DifficultyMask`, `VerifiedBuild`) VALUES
(35170, 'Tank', '$bullet;|cFF2959D3|Hspell:472662|h[Tempest Slash]|h|r knocks The Restless Heart\'s primary target away and briefly increases their Physical damage taken.\n$bullet;|cFF2959D3|Hspell:1253977|h[Turbulent Arrows]|h|r knock players into the air when touched, removing |cFF2959D3|Hspell:1216042|h[Squall Leap]|h|r.\n$bullet;|cFF2959D3|Hspell:1253986|h[Gust Shot]|h|r destroys any |cFF2959D3|Hspell:1282932|h[Storming Soulfonts]|h|r struck.', 2658, 6, 30469, 0, 30472, 3, 0, 0, 0, 0, 2, 1, 0, 65893),
(35169, 'Healer', '$bullet;|cFF2959D3|Hspell:474528|h[Bolt Gale]|h|r inflicts heavy damage to the targeted player.\n$bullet;|cFF2959D3|Hspell:1253977|h[Turbulent Arrows]|h|r knock players into the air when touched, removing |cFF2959D3|Hspell:1216042|h[Squall Leap]|h|r.\n$bullet;|cFF2959D3|Hspell:1253986|h[Gust Shot]|h|r destroys any |cFF2959D3|Hspell:1282932|h[Storming Soulfonts]|h|r struck.', 2658, 4, 30469, 0, 30471, 3, 0, 0, 0, 0, 2, 4, 0, 65893),
(34729, 'Xal\'atath\'s Bargains', 'Starting at Mythic Level 5, Xal\'atath periodically offers bargains during a Mythic Keystone dungeon that empower enemies. Players can intercept these effects and harness the power for themselves. These affixes rotate weekly.', 2870, 9, 0, 34751, 34730, 2, 0, 0, 0, 1728724, 1, 0, -1, 65893),
(34708, 'Downgrading a Mythic Keystone', '$bullet;Failing to complete the dungeon within the time limit lowers that Keystone\'s Mythic Level by 1.\n$bullet;Resetting the dungeon instance after the Keystone has been used lowers that Keystone\'s Mythic Level by 1.\n$bullet;Lindormi in major cities can lower a Keystone by 1 Mythic Level on request.', 2869, 4, 34737, 0, 34709, 0, 0, 0, 0, 0, 0, 0, -1, 65893),
(33687, 'Aura of Wrath', '', 2737, 10, 33680, 34917, 35118, 2, 0, 0, 1248449, 0, 2, 4128, 0, 65893),
(33639, 'Stage Three: Midnight Falls', 'Time is up. Can you end the ending itself?', 2740, 118, 0, 34000, 0, 0, 0, 0, 0, 0, 0, 0, -1, 65893),
(16066, 'Overview', 'Saprish cover the battlefield with|cFF2959D3|Hspell:246026|h[Void Bomb]|h|r and rushes players with |cFF2959D3|Hspell:1263516|h[Phase Dash]|h|r.\n\nAt 100 energy, Saprish casts |cFF2959D3|Hspell:1263526|h[Overload]|h|r that ignites all |cFF2959D3|Hspell:246026|h[Void Bomb]|h|r.', 1980, 1, 0, 16067, 16070, 3, 0, 0, 0, 0, 0, 0, -1, 65893),
(31296, 'Healers', '$bullet;|cFF2959D3|Hspell:473898|h[Legion Strike]|h|r inflicts heavy Physical damage and reduces incoming healing.\n\n$bullet;|cFF2959D3|Hspell:1214637|h[Axe Toss]|h|r targets a random player and applies |cFF2959D3|Hspell:1214650  |h[Fel Lightning]|h|r to all players until the axe is destroyed.', 2681, 3, 31293, 0, 31295, 3, 0, 0, 0, 0, 0, 4, -1, 65893),
(31294, 'Damage Dealers', '$bullet;|cFF2959D3|Hspell:474231|h[Burning Steps]|h|r leaves damaging pools of fel magic on the ground for a long duration.\n\n$bullet;|cFF2959D3|Hspell:1214637|h[Axe Toss]|h|r targets a random player and applies |cFF2959D3|Hspell:1214650  |h[Fel Lightning]|h|r to all players until the axe is destroyed.', 2681, 2, 31293, 0, 31296, 3, 0, 0, 0, 0, 0, 2, -1, 65893),
(31996, 'Section 8', '', 2660, 18, 0, 31995, 0, 2, 0, 0, 1284958, 0, 0, 4, -1, 65893),
(33689, 'Divine Storm', '$[!16\n\nIn Mythic difficulty, Zealous Spirit\'s empowerment causes Divine Storm to create several Divine Tempests that slowly converge on Lightblood.$]', 2737, 21, 33680, 34893, 33690, 2, 0, 0, 1246765, 0, 2, 0, 0, 65893),
(32176, 'Damage Dealers', '$bullet;|cFF2959D3|Hspell:1245391|h[Gloom]|h|r applies |cFF2959D3|Hspell:1245554|h[Gloomtouched]|h|r upon contact and shrinks the |cFF2959D3|Hspell:1245420|h[Gloomfield]|h|r formed.\n$[15,16$bullet;|cFF2959D3|Hspell:1262623|h[Nullbeam]|h|r creates a |cFF2959D3|Hspell:1244672|h[Nullzone]|h|r tethering players, causing |cFF2959D3|Hspell:1244413|h[Nullsnap]|h|r or |cFF2959D3|Hspell:1252157|h[Nullzone Implosion]|h|r when stretching the tether.$]\n$[14,17$bullet;|cFF2959D3|Hspell:1262623|h[Nullbeam]|h|r creates a |cFF2959D3|Hspell:1244672|h[Nullzone]|h|r tethering players, causing |cFF2959D3|Hspell:1244413|h[Nullsnap]|h|r when stretching the tether.$]\n$[14,15,16$bullet;|cFF2959D3|Hspell:1244221|h[Dread Breath]|h|r targets a player but affects all players in front of Vaelgor.$]\n$[17$bullet;|cFF2959D3|Hspell:1244917|h[Void Howl]|h|r summons Voidorbs which continually cast |cFF2959D3|Hspell:1245175|h[Voidbolt]|h|r.$]\n$[14,15,16$bullet;Manifestation of Midnight\'s |cFF2959D3|Hspell:1270497|h[Shadowmark]|h|r detonates upon expiration.$]', 2735, 2, 32175, 0, 32177, 3, 0, 0, 0, 0, 0, 2, -1, 65893),
(31261, 'Dark Entity', '', 2656, 10, 31242, 35166, 0, 1, 125228, 0, 0, 0, 1, 0, -1, 65893),
(32167, 'Overview', 'Averzian uses |cFF2959D3|Hspell:1251361|h[Shadow\'s Advance]|h|r to claim territory on the battlefield. Territory claimed cannot be retaken, and if Averzian claims three adjacent territories in a row he unleashes the |cFF2959D3|Hspell:1251583|h[March of the Endless]|h|r.\n\nCausing an |cFF2959D3|Hspell:1249262|h[Umbral Collapse]|h|r on a territory being taken prevents its capture.', 2733, 1, 0, 32168, 34566, 3, 0, 0, 0, 0, 0, 0, -1, 65893),
