(31306, 'Healers', '$bullet; |cFF2959D3|Hspell:1217345|h[Malefic Wave]|h|r  applies lingering damage over time when players using Lithiel\'s |cFF2959D3|Hspell:1214675|h[Demonic Gateway]|h|r pass through |cFF2959D3|Hspell:1217345|h[Malefic Wave]|h|r.\n\n$bullet;Furious Vilefiend inflicts heavy damage.', 2682, 4, 31303, 0, 0, 3, 0, 0, 0, 0, 0, 4, -1, 65893),
(31305, 'Tanks', '$bullet; |cFF2959D3|Hspell:474375|h[Chaos Bolt]|h|r inflicts high damage to a random target if not interrupted.\n\n$bullet;Furious Vilefiend inflicts heavy damage.', 2682, 3, 31303, 0, 31306, 3, 0, 0, 0, 0, 0, 1, -1, 65893),
(31304, 'Damage Dealers', '$bullet; |cFF2959D3|Hspell:1217345|h[Malefic Wave]|h|r grants |cFF2959D3|Hspell:1226469|h[Malefic Empowerment]|h|r to any summoned demons still alive when it passes over them.\n\n$bullet; |cFF2959D3|Hspell:474375|h[Chaos Bolt]|h|r inflicts high damage to a random target if not interrupted.', 2682, 2, 31303, 0, 31305, 3, 0, 0, 0, 0, 0, 2, -1, 65893),
(31295, 'Tanks', '$bullet;|cFF2959D3|Hspell:473898|h[Legion Strike]|h|r inflicts heavy Physical damage and reduces incoming healing.\n\n$bullet;|cFF2959D3|Hspell:474231|h[Burning Steps]|h|r creates damaging pools of fel magic that expand from Xathuux the Annihilator\'s location and remain on the ground for a long duration.', 2681, 4, 31293, 0, 0, 3, 0, 0, 0, 0, 0, 1, -1, 65893),
(35337, 'Safeguard Matrix', '', 2740, 23, 35336, 35338, 35339, 1, 136326, 0, 0, 0, 1, 0, -1, 65893);
