INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Swift Spectral Dragonhawk', '|cFFFFD200Legacy|r', 'Even the dead need a lift every now and then.', 2969, 242, 64, 5, 1289395, 0, 0, 4, 0, 0, 65893),
('Ashes of Belo\'ren', '|cFFFFD200Drop: |rMidnight Falls|n|cFFFFD200Location: |rMarch on Quel\'Danas (Mythic)', 'One of Al\'ar\'s last clutch, Belo\'ren was taken to the Isle of Quel\'Danas and raised to defend the Sunwell from any who would threaten it with his very life. It is said that death will never claim him.', 2607, 424, 0, 0, 1242904, 0, 0, 228, 0, 0, 65893),
('Vicious Snaplizard', '|cFFFFD200PvP:|r Midnight: Season 1|nRated Arena and Rated Battleground Season Reward', 'These creatures are found sneaking through the battlefield and climbing over obstactles, ready to cause trouble for the Horde.', 2794, 230, 4, 5, 1261648, 0, 0, 4, 0, 0, 65893),
('Vicious Snaplizard', '|cFFFFD200PvP:|r Midnight: Season 1|nRated Arena and Rated Battleground Season Reward', 'These creatures are found sneaking through the battlefield and climbing over obstactles, ready to cause trouble for the Alliance.', 2793, 230, 4, 5, 1261629, 0, 0, 4, 0, 0, 65893),
('Swift Springstrider', '|cFFFFD200Vendor: |rNoblegarden Merchant|n|cFFFFD200Zone: |rDurotar, Eversong Woods (Burning Crusade), Mulgore, Tirisfal Glades, Azuremyst Isle, |nDun Morogh, Elwynn Forest, Teldrassil|n|cFFFFD200Cost: |r500|TINTERFACE\\ICONS\\ACHIEVEMENT_NOBLEGARDEN_CHOCOLATE_EGG.BLP:0|t|n', 'The joys of Noblegarden are best when celebrated with this loyal, loving, and blandly-colored freak of nature.', 430, 230, 0, 6, 102349, 0, 0, 4, 0, 0, 65893),
('Swift Purple Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Their plumage is more beautiful than any other. Subtlety is for the birds! I mean... other birds. -Viera Sunwhisper', 161, 230, 0, 2, 35027, 0, 0, 44, 0, 0, 65893),
('Swift Green Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Their plumage is more beautiful than any other. Subtlety is for the birds! I mean... other birds. -Viera Sunwhisper', 160, 230, 0, 2, 35025, 0, 0, 44, 0, 0, 65893),
('Black Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Some of our brethren prefer horses, but the hawkstrider will always be the true symbol of Silvermoon. -Winaestra', 159, 230, 0, 2, 35022, 0, 0, 44, 0, 0, 65893),
('Blue Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Some of our brethren prefer horses, but the hawkstrider will always be the true symbol of Silvermoon. -Winaestra', 158, 230, 0, 2, 35020, 0, 0, 44, 0, 0, 65893),
('Purple Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Some of our brethren prefer horses, but the hawkstrider will always be the true symbol of Silvermoon. -Winaestra', 157, 230, 0, 2, 35018, 0, 0, 44, 0, 0, 65893),
('Red Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', 'Some of our brethren prefer horses, but the hawkstrider will always be the true symbol of Silvermoon. -Winaestra', 152, 230, 0, 2, 34795, 0, 0, 44, 0, 0, 65893),
('Swift Pink Hawkstrider', '|cFFFFD200Vendor: |rWinaestra|n|cFFFFD200Zone: |rEversong Woods (Burning Crusade)|n|cFFFFD200Cost: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Their plumage is more beautiful than any other. Subtlety is for the birds! I mean... other birds.\" -Viera Sunwhisper', 146, 230, 0, 2, 33660, 0, 0, 44, 0, 0, 65893);
